#!/bin/sh
# nfs2: server in tenant storage, VLAN 20, cabled to leaf4. Generated by fabctl render.
# Its gateway 10.20.20.1 is the anycast gateway: the same address and MAC on every leaf.
set -e
ip link set eth1 mtu 1500 up
ip addr replace 10.20.20.12/24 dev eth1
ip route replace default via 10.20.20.1
